def _df_from(fixture, code):
    n = len(fixture)
    return pl.DataFrame({
        "code": [code] * n,
        "date": [date.fromisoformat(r[0]) for r in fixture],
        "open": [r[1] for r in fixture],
        "high": [r[2] for r in fixture],
        "low": [r[3] for r in fixture],
        "close": [r[4] for r in fixture],
        "volume": [float(r[5]) for r in fixture],
        "adj_factor": [float(r[6]) for r in fixture],
    })


def _run_selector(df, market_cap):
    defn = make_macd_ma_convergence_defn()
    sel = defn.selector_class(defn)
    warmup = sel.warmup(df)
    ctx = SelectionContext(
        trade_date=df["date"].max(),
        market_data=df,
        candidate_codes=df["code"].unique().to_list(),
        market_cap=market_cap,
    )
    return sorted(sel.select_day(ctx, warmup).selected_codes)


def _reference_hit(df):
    """朴素逐行实现（前复权价）：每只股票最后一天 SELECT 是否命中。"""
    def ema(seq, n):
        a = 2 / (n + 1); y = [seq[0]]
        for t in range(1, len(seq)):
            y.append(a * seq[t] + (1 - a) * y[-1])
        return y

    def ma(seq, n):
        return [sum(seq[max(0, i - n + 1):i + 1]) / len(seq[max(0, i - n + 1):i + 1]) for i in range(len(seq))]

    out = {}
    for g in df.partition_by("code"):
        code = g["code"][0]
        g = g.sort("date")
        cs = g["close"].to_list()
        adj = g["adj_factor"].to_list()
        n = len(cs); i = n - 1
        if n < 234:
            out[code] = False
            continue
        al = adj[-1]
        cq = [c * (a / al) for c, a in zip(cs, adj)]

        ma34 = ma(cq, 34)[i]; ma55 = ma(cq, 55)[i]
        ma144 = ma(cq, 144)[i]; ma233 = ma(cq, 233)[i]
        spread = (ma55 - ma34) / ma34 * 100
        center = (ma34 + ma55 + ma144 + ma233) / 4
        dif = [e12 - e26 for e12, e26 in zip(ema(cq, 12), ema(cq, 26))][i]

        out[code] = bool(
            ma34 < ma55 and 2 < spread < 6
            and ma144 > ma233 and (ma144 - ma233) / ma233 * 100 > 1.5
            and ma144 > ma55 and ma144 > ma233
            and ma34 < center * 0.99
            and cq[i] > ma55 and cq[i] < ma144
            and cq[i] > min(ma34, ma55, ma144, ma233)
            and dif > 0
        )
    return out


def test_real_fixture_matches_reference():
    """真实行情：000751 公式命中、000001 不命中；selector 与参考一致。"""
    df = pl.concat([_df_from(_FIXTURE_HIT, "000751"), _df_from(_FIXTURE_MISS, "000001")])
    ref = _reference_hit(df)
    assert ref["000751"] is True, "真实样本 000751 应命中公式"
    assert ref["000001"] is False, "真实样本 000001 应不命中"
    assert _run_selector(df, {"000751": 600000.0, "000001": 600000.0}) == ["000751"]


def test_mvok_strict_above_50_yi():
    """公式 市值>50（严格大于）：恰好 50 亿不入选。"""
    df = _df_from(_FIXTURE_HIT, "000751")
    assert _run_selector(df, {"000751": 500000.0}) == []
    assert _run_selector(df, {"000751": 500001.0}) == ["000751"]


def test_requires_market_cap_flag():
    defn = make_macd_ma_convergence_defn()
    assert defn.selector_class.REQUIRES_MARKET_CAP is True
